169	    /**
170	     * Return this owner's name formatted as {@code LastName, FirstName}.
171	     */
172	    @Transient
173	    public String getDisplayName() {
174	        return this.getLastName() + ", " + this.getFirstName();
175	    }
176	
177	    /**
178	     * Return this owner's identity key: the single value all duplicate detection is based on,
179	     * formed as {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or
180	     * household id contributes an empty segment). Two owners are duplicates only when their whole
181	     * identity keys are equal, so members of the same household with different telephones — and thus
182	     * different keys — are distinct. The telephone and email are expected to already be in their
183	     * normalized storage form.
184	     */
185	    @Transient
186	    public String getIdentityKey() {
187	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
188	    }
189	
190	    private static String orEmpty(String value) {
191	        return value == null ? "" : value;
192	    }
193	
194	    /**
195	     * Return this owner's locality: the REGION segment of the owner's
196	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
197	     * When no customer code has been assigned yet the region is resolved directly from the
198	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
199	     */
200	    @Transient
201	    public String getLocality() {
202	        if (this.customerCode != null && !this.customerCode.isBlank()) {
203	            return CustomerCodeGenerator.regionOf(this.customerCode);
204	        }
205	        return RegionResolver.regionFor(this.postcode, this.city);
206	    }
207	
208	    /**
209	     * Return this owner's membership level: starting at 1, plus 1 when the owner
210	     * has an email, plus 1 when the owner is uniquely named (a
211	     * {@link #getNamesakeCount() namesakeCount} of 0), capped at 3. Level 4 is
212	     * reserved for tenure.
213	     */
214	    @Transient
215	    public int getMembershipLevel() {
216	        int level = 1;
217	        boolean hasEmail = this.email != null && !this.email.isEmpty();
218	        if (hasEmail) {
219	            level++;
220	        }
221	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
222	        if (uniquelyNamed) {
223	            level++;
224	        }
225	        return Math.min(level, 3);
226	    }
227	
228	    /**
229	     * Return this owner's check digit: the single Luhn check digit computed over the
230	     * digits of the {@link #getCustomerCode() customer code}.
231	     */
232	    @Transient
