237	    /**
238	     * Return this owner's preferred contact channel: {@code EMAIL} when an
239	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
240	     */
241	    @Transient
242	    public String getContactPreference() {
243	        boolean hasEmail = this.email != null && !this.email.isEmpty();
244	        return hasEmail ? "EMAIL" : "PHONE";
