253	
254	    protected void setPetsInternal(Set<Pet> pets) {
255	        this.pets = pets;
256	    }
257	
258	    public List<Pet> getPets() {
259	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
260	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
261	        return Collections.unmodifiableList(sortedPets);
262	    }
263	
264	    public void setPets(List<Pet> pets) {
265	        this.pets = new HashSet<>(pets);
266	    }
267	
268	    public void addPet(Pet pet) {
269	        getPetsInternal().add(pet);
270	        pet.setOwner(this);
271	    }
272	
273	    /**
274	     * Return the Pet with the given name, or null if none found for this Owner.
275	     *
276	     * @param name to test
277	     * @return true if pet name is already in use
278	     */
279	    public Pet getPet(String name) {
280	        return getPet(name, false);
281	    }
282	
283	    /**
284	     * Return the Pet with the given name, or null if none found for this Owner.
285	     *
286	     * @param name to test
287	     * @return true if pet name is already in use
288	     */
289	    public Pet getPet(String name, boolean ignoreNew) {
290	        name = name.toLowerCase();
291	        for (Pet pet : getPetsInternal()) {
292	            if (!ignoreNew || !pet.isNew()) {
293	                String compName = pet.getName();
294	                compName = compName.toLowerCase();
295	                if (compName.equals(name)) {
296	                    return pet;
297	                }
298	            }
299	        }
300	        return null;
301	    }
302	
303	    public Pet getPet(Integer petId) {
304	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
305	    }
306	
307	    @Override
308	    public String toString() {
309	        return new ToStringCreator(this)
310	
311	            .append("id", this.getId())
312	            .append("new", this.isNew())
313	            .append("lastName", this.getLastName())
314	            .append("firstName", this.getFirstName())
