46	import org.springframework.web.bind.annotation.ResponseBody;
47	
48	/**
49	 * Global Exception handler for REST controllers.
50	 * <p>
51	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
52	 *
53	 * @author Vitaliy Fedoriv
54	 * @author Alexander Dudkin
55	 */
56	@ControllerAdvice
57	public class ExceptionControllerAdvice {
58	
59	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
60	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
61	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
62	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
63	
64	    /**
65	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
66	     * class.
67	     *
68	     * @param e     Object referring to the thrown exception.
69	     * @param status HTTP response status.
70	     * @param url URL request.
71	     */
72	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
73	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
74	        problemDetail.setType(URI.create(url.toString()));
75	        problemDetail.setTitle(e.getClass().getSimpleName());
76	        problemDetail.setDetail(detail);
77	        problemDetail.setProperty("timestamp", Instant.now());
78	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
79	        return problemDetail;
80	    }
81	
82	    /**
83	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
84	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
85	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
86	     * would catch it and report an authorization failure as a 500.
87	     *
88	     * @param e The {@link AccessDeniedException} to propagate
89	     * @throws AccessDeniedException always
90	     */
91	    @ExceptionHandler(AccessDeniedException.class)
92	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
93	        throw e;
94	    }
95	
96	    /**
97	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
98	     *
99	     * @param e The {@link Exception} to be handled
100	     * @param request {@link HttpServletRequest} object referring to the current request.
101	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
102	     */
103	    @ExceptionHandler(Exception.class)
104	    @ResponseBody
105	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
106	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
107	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
108	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
109	        return ResponseEntity.status(status).body(detail);
110	    }
111	
112	    /**
113	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
114	     * method returns a 404 Not Found status if an entity does not exist.
115	     *
116	     * @param e The {@link DataIntegrityViolationException} to be handled
117	     * @param request {@link HttpServletRequest} object referring to the current request.
118	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
119	     */
120	    @ExceptionHandler(DataIntegrityViolationException.class)
121	    @ResponseBody
122	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
123	        logger.warn("Data integrity violation at {} {}: {}",
124	            request.getMethod(),
125	            request.getRequestURI(),
126	            e.getMessage());
127	        logger.debug("Data integrity violation stacktrace", e);
128	        HttpStatus status = HttpStatus.NOT_FOUND;
129	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
130	        return ResponseEntity.status(status).body(detail);
131	    }
132	
133	    /**
134	     * Handles exception thrown by Bean Validation on controller methods parameters
135	     *
136	     * @param e The {@link MethodArgumentNotValidException} to be handled
137	     * @param request {@link HttpServletRequest} object referring to the current request.
138	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
139	     */
140	    @ExceptionHandler(MethodArgumentNotValidException.class)
141	    @ResponseBody
142	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
143	        HttpStatus status = HttpStatus.BAD_REQUEST;
144	        BindingErrorsResponse errors = new BindingErrorsResponse();
145	        BindingResult bindingResult = e.getBindingResult();
146	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
147	        List<String> fieldNames = bindingResult.getFieldErrors().stream()
148	            .map(FieldError::getField)
149	            .distinct()
150	            .toList();
151	        detail.setProperty("errors", fieldNames);
152	        if (bindingResult.hasErrors()) {
153	            errors.addAllErrors(bindingResult);
154	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
155	                .map(fieldError -> {
156	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
157	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
158	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
159	                        fieldError.getField(),
160	                        defaultMessage,
161	                        rejectedValue);
162	                    return new ValidationMessageDto(message)
163	                        .putAdditionalProperty("field", fieldError.getField())
164	                        .putAdditionalProperty("rejectedValue", rejectedValue)
165	                        .putAdditionalProperty("defaultMessage", defaultMessage);
166	                })
167	                .toList();
168	            logger.debug("Validation error at {} {}: {}",
169	                request.getMethod(),
170	                request.getRequestURI(),
171	                bindingResult.getFieldErrors());
172	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
173	            return ResponseEntity.status(status).body(detail);
174	        }
175	        return ResponseEntity.status(status).body(detail);
176	    }
177	
178	    /**
179	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created or updated with
180	     * required fields that are missing or blank. Returns a 400 Bad Request whose body carries an
181	     * {@code errors} array listing the name of each offending field.
182	     *
183	     * @param e The {@link MissingOwnerFieldsException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
186	     */
187	    @ExceptionHandler(MissingOwnerFieldsException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
190	        HttpStatus status = HttpStatus.BAD_REQUEST;
191	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
192	        detail.setProperty("errors", e.getMissingFields());
193	        logger.debug("Missing or blank required fields at {} {}: {}",
194	            request.getMethod(),
195	            request.getRequestURI(),
196	            e.getMissingFields());
197	        return ResponseEntity.status(status).body(detail);
198	    }
199	
200	    /**
201	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone cannot be converted
202	     * to a valid E.164 number ({@code '+'} followed by 8 to 15 digits). Returns a 400 Bad Request
203	     * whose body carries an {@code errors} array naming the {@code telephone} field.
204	     *
205	     * @param e The {@link InvalidTelephoneException} to be handled
206	     * @param request {@link HttpServletRequest} object referring to the current request.
207	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
208	     */
209	    @ExceptionHandler(InvalidTelephoneException.class)
210	    @ResponseBody
211	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
212	        HttpStatus status = HttpStatus.BAD_REQUEST;
213	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
214	        detail.setProperty("errors", List.of("telephone"));
215	        logger.debug("Invalid telephone at {} {}: {}",
216	            request.getMethod(),
217	            request.getRequestURI(),
218	            e.getMessage());
219	        return ResponseEntity.status(status).body(detail);
220	    }
221	
222	    /**
223	     * Handles {@link InvalidEmailException} raised when an owner's submitted email is present but
224	     * is not a syntactically valid address. Returns a 400 Bad Request whose body carries an
225	     * {@code errors} array naming the {@code email} field.
226	     *
227	     * @param e The {@link InvalidEmailException} to be handled
228	     * @param request {@link HttpServletRequest} object referring to the current request.
229	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
230	     */
231	    @ExceptionHandler(InvalidEmailException.class)
232	    @ResponseBody
233	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
234	        HttpStatus status = HttpStatus.BAD_REQUEST;
235	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
236	        detail.setProperty("errors", List.of("email"));
237	        logger.debug("Invalid email at {} {}: {}",
238	            request.getMethod(),
