242	    }
243	
244	    /**
245	     * Handles {@link InvalidPostcodeException} raised when an owner's supplied postcode is out of
246	     * range for its city's region. Returns a 400 Bad Request whose body carries an {@code errors}
247	     * array naming the {@code postcode} field.
248	     *
249	     * @param e The {@link InvalidPostcodeException} to be handled
250	     * @param request {@link HttpServletRequest} object referring to the current request.
251	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
252	     */
253	    @ExceptionHandler(InvalidPostcodeException.class)
254	    @ResponseBody
255	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
256	        HttpStatus status = HttpStatus.BAD_REQUEST;
