265	
266	    /**
267	     * Handles {@link DuplicateOwnerIdentityException} raised when an owner is created whose whole
268	     * identity key (normalized telephone, email and household id) already belongs to another owner.
269	     * Returns a 409 Conflict whose body carries an {@code errors} array naming the
270	     * {@code identityKey}.
271	     *
272	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
273	     * @param request {@link HttpServletRequest} object referring to the current request.
274	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
275	     */
276	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
277	    @ResponseBody
278	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
279	        HttpStatus status = HttpStatus.CONFLICT;
